const fetch = require('node-fetch');

// Remove crases, espaços e ponto e vírgula final (a função do banco rejeita ";")
const cleanSql = $sql
  .trim()
  .replace(/```sql/gi, '')
  .replace(/```/g, '')
  .trim()
  .replace(/;+\s*$/, '');

// Camada de segurança: colunas confidenciais e tabela base
if (/\b(employee_id|age|salary|phone|performance_score|baserh)\b/i.test(cleanSql)) {
  return 'resultado: BLOQUEADO';
}

const SUPABASE_URL = 'SUPABASE_URL ';
const SUPABASE_KEY = 'SUPABASE_KEY';

try {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/rpc/execute_sql`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`
    },
    body: JSON.stringify({ query: cleanSql })
  });

  const data = await res.json();

  if (!res.ok) {
    const msg = data.message || JSON.stringify(data);
    // A função do banco também barra colunas confidenciais
    if (msg.includes('BLOQUEADO')) {
      return 'resultado: BLOQUEADO';
    }
    return 'Erro na consulta: ' + msg;
  }

  // Garante que é um array
  const rows = Array.isArray(data) ? data : (data ? [data] : []);

  if (rows.length === 0) {
    return 'Nenhum registro encontrado.';
  }

  // Converte JSON para texto legível: "coluna: valor" separados por " | "
  return rows
    .map(row =>
      Object.entries(row)
        .map(([key, value]) => `${key}: ${value === null ? 'NULL' : value}`)
        .join(' | ')
    )
    .join('\n');

} catch (e) {
  return 'Erro na consulta: ' + e.message;
}

